import{z as n,x as c,o as r,c as p,q as o,j as s,D as e,d,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"三地址中间表示","description":"","frontmatter":{"title":"三地址中间表示","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ir-three-address.md","filePath":"cs/ir-three-address.md","lastUpdated":1791413859000}'),A={name:"cs/ir-three-address.md"};function B(h,a,E,_,m,f){const t=c("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="三地址中间表示" tabindex="-1">三地址中间表示 <a class="header-anchor" href="#三地址中间表示" aria-label="Permalink to &quot;三地址中间表示&quot;">​</a></h1><div class="epigraph"><p>把表达式树压成 $x\\leftarrow y\\,\\mathrm{op}\\,z$ 的序列，控制流用跳转与标号；前端与 ISA 在此脱钩。</p><footer>—— 据龙书第 6、8 章整理</footer></div><p>上一课<a href="/cs/overload-coerce">overload 与强制</a>保证节点有类型与宽度。本课不重写类型规则。缺口是：AST 嵌套不便做数据流与指令选择。三地址码（或等价的四元组）把计算写成最多两个源、一个目的，临时变量无限。本课只钉这种 IR 的形状；SSA 是后课加的约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AST 上的 <code>a+b*c</code> 要规定求值顺序、临时名、以及 <code>if</code> 的跳转。若直接对<a href="/cs/riscv-int-isa">RISC-V</a> 发指令，优化绑死 ISA，前端无法共用。<a href="/cs/compiler-passes">编译器通行证</a>已经声明中端存在；本课给出对象：指令表 + 基本块。</p><p>三地址不是物理寄存器：名字是虚拟的。数组下标、指针解引用写成带类型宽度的 <code>load/store</code>。调用写成 <code>call</code>，参数按抽象约定，具体寄存器在 ABI 课。</p><p><span class="marginnote">术语翻译：三地址码就是「每条指令最多三个地址」的中间代码——两个地址放源操作数、一个放结果，<code>a+b*c</code> 这样的复杂表达式被拆成一串每次只做一件事的小步骤。</span></p><h3 id="三地址不是「只能三个数」" tabindex="-1">三地址不是「只能三个数」 <a class="header-anchor" href="#三地址不是「只能三个数」" aria-label="Permalink to &quot;三地址不是「只能三个数」&quot;">​</a></h3><p>名字来自最多两个操作数加结果。比较与跳转、过程调用、φ 还没有。基本块：单入口单出口的直线序列。块间构成 CFG——算法课的<a href="/cs/graph-definition">图</a>在此第一次成为程序的控制图，不是源文本。</p><p><span class="marginnote">龙书用三地址作中端教科书 IR。四元式 \\((op,y,z,x)\\) 是同一信息。LLVM IR 等是工业形态，本课不搬家。无限临时由后课寄存器分配收紧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>后序遍历表达式：为每个内节点分配临时，发一条指令。布尔与短路做成跳转。循环拆成条件跳与回边。输出：指令列表或块链表。</p>',12)),(r(),s(l,null,{default:e(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AST%5B%22%E7%B1%BB%E5%9E%8B%E6%AD%A3%E7%A1%AE%E7%9A%84%20AST%22%5D%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%E4%B8%89%E5%9C%B0%E5%9D%80%22%5D%0A%20%20LIN%20--%3E%20CFG%5B%22%E5%9F%BA%E6%9C%AC%E5%9D%97%20CFG%22%5D%0A%20%20CFG%20--%3E%20OPT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ASSA%20%E4%B8%8E%E6%95%B0%E6%8D%AE%E6%B5%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><a href="/cs/dag-repr">DAG</a> 可在块内表示公共子表达式，本课允许块内 DAG，不强制全局。临时名按出现次序编号即可，不必此时就 SSA。</p><p><span class="marginnote">数字实例：<code>a+b*c</code> 压平后只有两条指令——<code>t1 = b * c</code>、<code>t2 = a + t1</code>：原本 5 个节点的表达式树（根 +、叶 a、内节点 *、叶 b、叶 c），变成 2 条三地址指令加 2 个按次序编号的临时名。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>IR 使窥孔、活跃变量、指令选择有固定接口。正确性：与 AST 的求值语义一致，含短路与副作用顺序。临时变量的活跃区间下一课之后才算。不要在本课选物理寄存器。</p><p><span class="marginnote">常见误区：初学者容易以为临时变量会占真实寄存器。实际上三地址的名字是虚拟的、数量不限，塞进哪个物理寄存器是后端寄存器分配阶段的事，缺了还会溢出到栈。</span></p><p>条件分支 <code>if a \\lt b</code> 线性化后如何切块与跳转：</p>',6)),(r(),s(l,null,{default:e(()=>[i(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20B1%5B%22B1%3A%20if%20a%20%5Clt%20b%20goto%20B3%22%5D%20--%3E%7C%22%E7%9C%9F%22%7C%20B3%5B%22B3%3A%20x%20%3D%201%22%5D%0A%20%20B1%20--%3E%7C%22%E5%81%87%22%7C%20B2%5B%22B2%3A%20x%20%3D%202%3B%20goto%20B4%22%5D%0A%20%20B2%20--%3E%20B4%5B%22B4%3A%20%E4%B9%8B%E5%90%8E%E4%BB%A3%E7%A0%81%EF%BC%88%E4%BD%BF%E7%94%A8%20x%EF%BC%89%22%5D%0A%20%20B3%20--%3E%20B4%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[d(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SSA 的 φ、不做全局数据流、不选机器指令。不把解释器当 IR。后课默认：中端对象是三地址 + CFG。静态单赋值是后课对名字的约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三地址把树压成 \\(x\\leftarrow y\\,\\mathrm{op}\\,z\\) 与跳转。</li><li>基本块 CFG 才是可做数据流的图。</li><li>名字虚拟，未分配寄存器。</li><li>块内可收成 DAG；全局 SSA 是后课。</li><li>出处：Aho et al., 龙书第 6、8 章。</li></ul>',4))])}const C=n(A,[["render",B]]);export{T as __pageData,C as default};
